@Override public void onChanged(final List<EntityOperation> operations){
  boolean process=false;
  List<Long> ops=new ArrayList<>();
  for (EntityOperation op : operations) {
    try {
      if (!handling.contains(op.id)) process=true;
      ops.add(op.id);
    } catch (NullPointerException e) {
      Log.e("onChanged", "Null id in operation: " + op, e);
      continue;
    }
  }
  handling=ops;
  if (handling.size() > 0 && process) {
    Log.i(folder.name + " operations=" + operations.size());
    (folder.poll ? pollExecutor : folderExecutor).submit(new Runnable(){
      @Override public void run(){
        try {
          wlFolder.acquire();
          Log.i(folder.name + " process");
          Folder ifolder=folders.get(folder);
          final boolean shouldClose=(ifolder == null);
          try {
            Log.i(folder.name + " run " + (shouldClose ? "offline" : "online"));
            if (ifolder == null) {
              if (db.operation().getOperationCount(folder.id,null) == 0) return;
              db.folder().setFolderState(folder.id,"connecting");
              ifolder=istore.getFolder(folder.name);
              ifolder.open(Folder.READ_WRITE);
              db.folder().setFolderState(folder.id,"connected");
              db.folder().setFolderError(folder.id,null);
            }
            Core.processOperations(ServiceSynchronize.this,account,folder,isession,istore,ifolder,state);
          } catch (Throwable ex) {
            Log.e(folder.name,ex);
            Core.reportError(ServiceSynchronize.this,account,folder,ex);
            db.folder().setFolderError(folder.id,Helper.formatThrowable(ex,true));
            state.error();
          }
          finally {
            if (shouldClose) {
              if (ifolder != null && ifolder.isOpen()) {
                db.folder().setFolderState(folder.id,"closing");
                try {
                  ifolder.close(false);
                } catch (MessagingException ex) {
                  Log.w(folder.name,ex);
                }
              }
              if (folder.synchronize && (folder.poll || !capIdle)) db.folder().setFolderState(folder.id,"waiting");
              else db.folder().setFolderState(folder.id,null);
            }
          }
        } finally {
          wlFolder.release();
        }
      }
    });
  }
}
